use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let m = Arc::new(Mutex::new(0));
    let h = thread::spawn(move || {
        *m.lock().unwrap() += 1;
    });
    h.join().unwrap();
    println!("{}", m.lock().unwrap());
}

use std::sync::Arc;

fn main() {
    let a = Arc::new(1);
    let b = Arc::clone(&a);
    let c = Arc::clone(&b);
    println!("{}", Arc::strong_count(&a));
    drop(c);
    println!("{}", Arc::strong_count(&a));
}

use std::sync::RwLock;

fn main() {
    let l = RwLock::new(1);
    let a = l.read().unwrap();
    let b = l.read().unwrap();
    println!("{}", *a + *b);
}

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

fn main() {
    let n = Arc::new(AtomicUsize::new(0));
    let hs: Vec<_> = (0..3)
        .map(|i| {
            let n = Arc::clone(&n);
            thread::spawn(move || {
                n.fetch_add(i + 1, Ordering::SeqCst);
            })
        })
        .collect();
    for h in hs {
        h.join().unwrap();
    }
    println!("{}", n.load(Ordering::SeqCst));
}
